const root = $input.first().json;
const body = root.body || root;

// نتعامل فقط مع أحداث رسالة واردة فعلية من واها — أي حدث ثاني (تأكيد استلام،
// تغيير حالة، إلخ) نتجاهله كلياً بإرجاع مصفوفة فاضية عشان يوقف التنفيذ فوراً
// بدون أي رد (منعاً لحلقة لا نهائية).
const KNOWN_MESSAGE_EVENTS = ['message'];
if (!body || !KNOWN_MESSAGE_EVENTS.includes(body.event) || !body.payload) {
  return [];
}

const p = body.payload;

// رسالة صادرة منا احنا (رد آلي سبق أرسلناه، واها يرجع يبعتها كحدث) — نتجاهلها
// كلياً بإرجاع مصفوفة فاضية، حتى ما تدخل بحلقة لا نهائية.
if (p.fromMe) {
  return [];
}

const text = (p.body || '').trim();
const from = String(p.from || '');
const messageId = p.id || '';
const timestamp = p.timestamp || '';

// دعم الوسائط (صور/فيديوهات) — واها يرسل hasMedia:true وكائن media فيه
// تفاصيل الملف (الرابط/النوع) لما تكون الرسالة صورة أو فيديو أو غيرها.
const hasMedia = !!p.hasMedia;
const media = p.media || null;
let mediaUrl = media ? (media.url || media.link || '') : '';
// واها أحياناً يرجع رابط داخلي خاص بشبكة Railway (railway.internal) ما تقدر
// n8n توصله من برا. نستبدله بالرابط العام دائماً.
if (mediaUrl) {
  mediaUrl = mediaUrl.replace(/https?:\/\/[^\/]*railway\.internal(:\d+)?/, 'https://devlikeaprowaha-production-c7e8.up.railway.app');
}
const mediaMimetype = media ? (media.mimetype || media.mimeType || '') : '';
let mediaType = '';
if (hasMedia) {
  if (mediaMimetype.startsWith('image/')) mediaType = 'image';
  else if (mediaMimetype.startsWith('video/')) mediaType = 'video';
  else if (mediaMimetype.startsWith('audio/')) mediaType = 'audio';
  else mediaType = 'other';
}

return [{ json: { text, from, messageId, timestamp, hasText: !!text, hasMedia, mediaType, mediaUrl, mediaMimetype } }];

const incoming = $('قراءة نص الرسالة').first().json;
const normalizePhone = (p) => String(p || '').replace(/\D/g, '').replace(/^00/, '').slice(-10);
const fromNorm = normalizePhone(incoming.from);

const draftRows = $('جلب الحالة المعلقة').all().map(i => i.json).filter(r => r && r.phone);
const prevRow = draftRows.find(r => normalizePhone(r.phone) === fromNorm) || {};
const previousDraftJson = prevRow.draft_json || null;

const logRows = $('جلب سجل الحملات (للذاكرة)').all().map(i => i.json).filter(r => r && r.from);
const campaignHistory = logRows
  .filter(r => normalizePhone(r.from) === fromNorm)
  .map(r => ({
    campaign_id: r.campaign_id,
    name: r.name,
    platform: r.platform,
    budget: r.budget,
    status: r.status,
    client: r.client,
    success: r.success,
    created_at: r.createdAt || r.created_at || ''
  }))
  .slice(-30);

return [{ json: { text: incoming.text, from: incoming.from, previousDraftJson, campaignHistory } }];

const raw = $json.output;
let parsed = null;
if (typeof raw === 'string') {
  try { parsed = JSON.parse(raw); } catch (e) { parsed = null; }
} else if (raw && typeof raw === 'object') {
  parsed = raw;
}
const incoming = $('تجهيز سياق الـAI').first().json;
const defaults = {
  action: 'none', platform: '', platforms: [], client: '', ad_account_id: '',
  campaign_name: '', budget: '', currency: 'USD', objective: '', audience: '',
  location: '', status: '', campaign_id: '', date_range: '', general_reply: '',
  missing_info: ['فهم الرسالة'], needs_confirmation: false, confirmed: false,
  reply_message_if_incomplete: 'ما فهمت الطلب زين، تكدر تعيد الصياغة؟'
};
const result = parsed ? { ...defaults, ...parsed } : { ...defaults };
result.from = incoming.from;
result.rawText = incoming.text;
return [{ json: result }];

const ai = $('استخراج نتيجة الـAI').first().json;
const normalizePhone = (p) => String(p || '').replace(/\D/g, '').replace(/^00/, '').slice(-10);
const fromNorm = normalizePhone(ai.from);
const allRows = $input.all().map(i => i.json).filter(r => r && r.client);
let rows = allRows.filter(r => normalizePhone(r.phone) === fromNorm);
if (ai.client) {
  const byClient = rows.filter(r => String(r.client || '').trim() === String(ai.client).trim());
  if (byClient.length) rows = byClient;
}
const errors = [];
const platforms = ai.platforms;
const action = ai.action;

// محادثة عامة/سؤال عام مو متعلق بإدارة حملات — الذكاء الاصطناعي يرد مباشرة
// بدل ما نطلب منصة/اسم حملة/ميزانية مالها معنى بهذا السياق.
const isGeneralChat = (!action || action === 'none') && !!ai.general_reply;

if (!isGeneralChat) {
  if (!platforms || !platforms.length) errors.push('المنصة (فيسبوك أو تيك توك) غير محددة');
  if (!action || action === 'none') errors.push('نوع العملية غير واضح');
  if (action === 'create') {
    if (!ai.campaign_name) errors.push('اسم الحملة');
    if (!ai.budget) errors.push('الميزانية');
  }
  if (['activate','pause','delete','update_budget'].includes(action) && !ai.campaign_id) errors.push('رقم الحملة (campaign_id)');
  if (action === 'update_budget' && !ai.budget) errors.push('الميزانية الجديدة');
}

let metaAccountId = '';
let tiktokAdvertiserId = '';

if (!isGeneralChat) {
  if (rows.length > 1) {
    const options = rows.map(r => `${r.client}: Meta=${r.meta_ad_account_id||'-'} / TikTok=${r.tiktok_advertiser_id||'-'}`).join('\n');
    errors.push('فيه أكثر من حساب مرتبط برقمك، حدد اسم العميل بالضبط:\n' + options);
  } else if (rows.length === 1) {
    metaAccountId = rows[0].meta_ad_account_id || '';
    tiktokAdvertiserId = rows[0].tiktok_advertiser_id || '';
  } else {
    metaAccountId = platforms.includes('meta') ? (ai.ad_account_id || '') : '';
    tiktokAdvertiserId = platforms.includes('tiktok') ? (ai.ad_account_id || '') : '';
    if (platforms.includes('meta') && !metaAccountId) errors.push('ما لقيت عميل مرتبط برقمك، حدد اسم العميل أو رقم حساب Meta الإعلاني');
    if (platforms.includes('tiktok') && !tiktokAdvertiserId) errors.push('ما لقيت عميل مرتبط برقمك، حدد اسم العميل أو رقم حساب TikTok الإعلاني');
  }
}

const valid = errors.length === 0 && !isGeneralChat;
let validationMessage = '';
if (isGeneralChat) {
  validationMessage = ai.general_reply;
} else if (!valid) {
  validationMessage = '❌ ما كدرت أنفذ الطلب.\n' + errors.join('\n');
}

return [{ json: { ...ai, metaAccountId, tiktokAdvertiserId, valid, validationErrors: errors, validationMessage } }];

// استجابة API فيسبوك/تيك توك تستبدل بيانات العنصر بالكامل (يرجع بس id
// مثلاً)، فنفقد باقي التفاصيل (اسم الحملة، الميزانية...). نجيبها من نود
// "تحقق قبل التنفيذ" (قبل استدعاء المنصة) بدل الاعتماد على $json وحده.
const ctx = $('تحقق قبل التنفيذ').first().json;
const j = $json;
const body = j.body || j;
let error = '';
if (body && body.error) { error = body.error.message || (typeof body.error === 'string' ? body.error : JSON.stringify(body.error)); }
else if (j.error) { error = (typeof j.error === 'string') ? j.error : (j.error.message || JSON.stringify(j.error)); }
else if (body && body.message && body.success === false) { error = body.message; }
const success = !error;
const result = {
  id: body.id || ctx.campaign_id || '',
  status: body.status || ctx.status || 'PAUSED',
  platform: (Array.isArray(ctx.platforms) && ctx.platforms.length) ? ctx.platforms.join('+') : (ctx.platform || ''),
  name: ctx.campaign_name || '',
  budget: ctx.budget || '',
  from: ctx.from || '',
  campaign_id: body.id || ctx.campaign_id || '',
  client: ctx.client || '',
  created_at: new Date().toISOString(),
  action: ctx.action || '',
  success,
  error
};
return [{ json: result }];

const j = $json;
let msg;
if (j.success) {
  msg = `✅ تم ${j.action === 'create' ? 'إنشاء' : 'تنفيذ'} حملة ${j.name || j.campaign_id}\nالمنصة: ${j.platform}\nCampaign ID: ${j.campaign_id}\nالميزانية: $${j.budget || '-'}\nالحالة: ${j.status}`;
} else {
  msg = `❌ ما تم تنفيذ الطلب.\nالسبب: ${j.error || 'خطأ غير معروف من المنصة'}`;
}
return [{ json: { ...j, finalMessage: msg } }];

const incoming = $('قراءة نص الرسالة').first().json;
const normalizePhone = (p) => String(p || '').replace(/\D/g, '').replace(/^00/, '').slice(-10);
const fromNorm = normalizePhone(incoming.from);
const rows = $input.all().map(i => i.json).filter(r => r && r.phone);
const match = rows.find(r => normalizePhone(r.phone) === fromNorm);
const active = match ? !(String(match.active || '').trim().toLowerCase() === 'false') : false;
let authorized = !!match && active;

// بعض جهات الاتصال يظهر رقمها لواتساب/واها كمعرّف مخفي (@lid) بدل الرقم
// الحقيقي (خاصية خصوصية جديدة من واتساب نفسه) فما نكدر نطابقها مع الجدول
// إطلاقاً. الحل: أي رسالة تبدأ برمز سري متفق عليه تعتبر مصرح لها (نتقبل
// وجود أو عدم وجود مسافة بين الكلمة والرقم، مثل "كود1234" أو "كود 1234").
// نحذف الرمز من النص دائماً لو موجود، سواء انصرح عن طريق الرمز أو عن طريق
// تطابق الرقم مباشرة (حتى ما يوصل "كود 1234" للذكاء الاصطناعي ويلخبطه).
let text = incoming.text || '';
const codeMatch = text.trim().match(/^كود\s*1234\s*/);
if (codeMatch) {
  if (!authorized) authorized = true;
  text = text.trim().slice(codeMatch[0].length).trim();
}

if (!authorized) {
  return [];
}

return [{ json: { ...incoming, text, authorized } }];

const res = $input.first().json;
let text = res?.candidates?.[0]?.content?.parts?.[0]?.text;
const analysis = (typeof text === 'string' && text.trim())
  ? text.trim()
  : 'ما كدرت أحلل الفيديو هذي المرة (خطأ تقني). جرب ترسله مرة ثانية بعد شوي.';
return [{ json: { analysis } }];

const incoming = $('قراءة نص الرسالة').first().json;
const normalizePhone = (p) => String(p || '').replace(/\D/g, '').replace(/^00/, '').slice(-10);
const fromNorm = normalizePhone(incoming.from);
const rows = $input.all().map(i => i.json).filter(r => r && r.phone);
const match = rows.find(r => normalizePhone(r.phone) === fromNorm);
let draft = {};
if (match && match.draft_json) {
  try { draft = JSON.parse(match.draft_json) || {}; } catch (e) { draft = {}; }
}
draft.media_url = incoming.mediaUrl || '';
draft.media_type = incoming.mediaType || '';
draft.has_media = true;
return [{ json: { from: incoming.from, draft_json: JSON.stringify(draft) } }];

