const item = $input.first();
if (!item.binary || !item.binary.data) {
  return [{ json: { error: 'no_binary' } }];
}
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const mimeType = item.binary.data.mimeType || 'video/mp4';
return [{ json: { base64: buf.toString('base64'), mimeType } }];
